input.command:
cat > tests/export_test.sh <<'EOF'
#!/bin/bash
# export: a dry run prints one request line per batch.
fail=0
bash bin/export --rows 10 --dry-run | grep -q '^POST /v2/batch rows=1-10 ' || { echo "export dry-run"; fail=1; }
bash bin/export --bogus >/dev/null 2>&1; [ $? = 2 ] || { echo "export usage"; fail=1; }
# RLY-748: at most 250 rows per request (ADR-0012), remainder in the last one.
out=$(bash bin/export --rows 600 --dry-run)
echo "$out" | grep -q 'rows=1-250 ' && echo "$out" | grep -q 'rows=251-500 ' && echo "$out" | grep -q 'rows=501-600 ' || { echo "export batch size"; fail=1; }
[ "$(echo "$out" | wc -l)" = 3 ] || { echo "export batch count"; fail=1; }
# RLY-748: current auth header is X-Relay-Key; X-Partner-Token is rejected with 401 (CHANGELOG 2.4.0).
echo "$out" | grep -q ' X-Relay-Key$' || { echo "export auth header"; fail=1; }
echo "$out" | grep -q 'X-Partner-Token' && { echo "export old header"; fail=1; }
exit $fail
EOF
bash tests/export_test.sh; echo "before fix exit=$?"
sed -i 's|^# Batch size.*|# Batch size for the partner export (docs/adr/0012-partner-batch-size.md): at most 250 rows per request.|; s/^EXPORT_BATCH_ROWS=500/EXPORT_BATCH_ROWS=250/' lib/export/batch.sh
sed -i 's|^# Partner request helpers.*|# Partner request helpers. Auth header: X-Relay-Key (keyed auth since 2.3.0; X-Partner-Token dropped in 2.4.0), value from RELAY_PARTNER_KEY.|; s/^EXPORT_AUTH_HEADER=.*/EXPORT_AUTH_HEADER=X-Relay-Key/' lib/export/partner.sh
bash tests/export_test.sh; echo "after fix exit=$?"; bash scripts/verify.sh
